input.command:
F="/Users/iskang/.claude/projects/-Volumes-Data-AIStudio-workspace-ai-framework/05aa1095-7700-4bb5-bb4f-a12ab53a7b39.jsonl"
python3 -c "
import json
with open('$F') as f:
    for line in f:
        try:
            d = json.loads(line)
        except: continue
        msg = d.get('message', {})
        content = msg.get('content')
        if isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'tool_use' and c.get('name') in ('Task','Agent'):
                    print('TOOL_USE', d.get('timestamp'), d.get('uuid'), c.get('id'), c.get('name'))
                if isinstance(c, dict) and c.get('type') == 'tool_result':
                    tid = c.get('tool_use_id')
                    print('TOOL_RESULT', d.get('timestamp'), d.get('uuid'), tid)
" | head -30
